//! The demo's large config (in the editor crate's `tests/fixtures/samples/`, generated by `samples/generate.py`)
//! checked through the editor crate's public headless API: every language's
//! file parses to the same document, validates against the demo
//! `schema.json`, converts losslessly into every other language, and the
//! hot paths stay fast on a document this size.

use config_editor_leptos::{Language, Schema};
use std::time::{Duration, Instant};

const SCHEMA: &str = include_str!("../schema.json");
const SAMPLES: [(Language, &str); 5] = [
    (
        Language::JSON,
        include_str!("../crates/config-editor-leptos/tests/fixtures/samples/tunnel.large.json"),
    ),
    (
        Language::YAML,
        include_str!("../crates/config-editor-leptos/tests/fixtures/samples/tunnel.large.yaml"),
    ),
    (
        Language::TOML,
        include_str!("../crates/config-editor-leptos/tests/fixtures/samples/tunnel.large.toml"),
    ),
    (
        Language::HCL,
        include_str!("../crates/config-editor-leptos/tests/fixtures/samples/tunnel.large.hcl"),
    ),
    (
        Language::XML,
        include_str!("../crates/config-editor-leptos/tests/fixtures/samples/tunnel.large.xml"),
    ),
];

fn schema() -> Schema {
    Schema::compile(SCHEMA).expect("the demo schema compiles")
}

#[test]
fn every_language_sample_parses_to_the_same_document() {
    let expected = Language::JSON.parse(SAMPLES[0].1).expect("JSON sample");
    for (language, source) in SAMPLES {
        assert!(source.lines().count() > 1500, "{language:?} sample is long");
        let document = language
            .parse(source)
            .unwrap_or_else(|error| panic!("{language:?}: {error}"));
        for (key, value) in expected.as_object().expect("an object") {
            assert_eq!(
                document.get(key),
                Some(value),
                "{language:?} differs at /{key}"
            );
        }
        assert_eq!(document, expected, "{language:?} has extra keys");
    }
}

#[test]
fn every_language_sample_validates_against_the_demo_schema() {
    let schema = schema();
    for (language, source) in SAMPLES {
        let problems = schema.validate(language, source);
        assert!(problems.is_empty(), "{language:?}: {problems:#?}");
    }
}

#[test]
fn every_sample_converts_losslessly_into_every_language() {
    let schema = schema();
    let expected = Language::JSON.parse(SAMPLES[0].1).expect("JSON sample");
    for (from, source) in SAMPLES {
        for (to, _) in SAMPLES {
            let converted = from
                .convert(source, to)
                .unwrap_or_else(|error| panic!("{from:?} -> {to:?}: {error}"));
            assert!(
                converted.losses.is_empty(),
                "{from:?} -> {to:?}: {:?}",
                converted.losses
            );
            assert_eq!(
                to.parse(&converted.text).expect("reads back"),
                expected,
                "{from:?} -> {to:?}"
            );
            let problems = schema.validate(to, &converted.text);
            assert!(problems.is_empty(), "{from:?} -> {to:?}: {problems:#?}");
        }
    }
}

/// Generous native budgets: they catch accidental quadratic work on a
/// ~2000-line document, not small regressions.
#[test]
fn validation_and_conversion_stay_fast_on_a_large_document() {
    let schema = schema();
    let budget = Duration::from_millis(500);
    for (language, source) in SAMPLES {
        let started = Instant::now();
        assert!(schema.validate(language, source).is_empty());
        let validate = started.elapsed();
        let started = Instant::now();
        let converted = language.convert(source, Language::HCL).expect("converts");
        let convert = started.elapsed();
        assert!(!converted.text.is_empty());
        println!("{language:?}: validate {validate:?}, convert to HCL {convert:?}");
        assert!(validate < budget, "{language:?} validate took {validate:?}");
        assert!(convert < budget, "{language:?} convert took {convert:?}");
    }
}
